<script setup lang="ts">
import {ElMessageBox} from 'element-plus'
import 'element-plus/es/components/message-box/style/css'
import {useRoute} from 'vue-router'
import {createRequestGuard,fetchDecisionBundle} from './requestGuard'
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {api,errorText,type Store} from './api'
interface Proposal{proposal_id:string;source_task_id:string;store_id:number;sku:string;proposal_type:string;title:string;description:string;risk_level:string;suggested_action:string;status:string;evidence_json:Record<string,unknown>;limitations_json:string[]}
const stores=ref<Store[]>([]),store=ref<number>(),tasks=ref<{task_id:string;user_query:string}[]>([]),source=ref(''),kind=ref(''),risk=ref(''),items=ref<Proposal[]>([]),selected=ref<Proposal>(),error=ref(''),message=ref(''),busy=ref(false),page=ref(1),total=ref(0)
const route=useRoute();const simulating=ref(false),simulation=ref<any>(),simulations=ref<any[]>([]),simPage=ref(1),simTotal=ref(0)
const reviewing=ref(false),comment=ref(''),audits=ref<{audit_id:string;action:string;from_status:string;to_status:string;reviewer_id:string;identity_source:string;comment:string;created_at:string}[]>([])
const statuses:Record<string,string>={draft:'草稿',pending_review:'待审核',approved:'已批准（未执行）',rejected:'已驳回'}
const listGuard=createRequestGuard(),detailGuard=createRequestGuard(),simGuard=createRequestGuard(),taskGuard=createRequestGuard();onBeforeUnmount(()=>{listGuard.invalidate();detailGuard.invalidate();simGuard.invalidate();taskGuard.invalidate()})
const types:Record<string,string>={profit_review:'亏损复核',ad_budget_review:'广告预算复核',replenishment_review:'补货复核',overstock_review:'积压复核',cost_change_review:'成本变化复核'}
async function load(){if(!store.value)return;const token=listGuard.begin();try{const r=await api.get('/decisions',{params:{store_id:store.value,proposal_type:kind.value||undefined,risk_level:risk.value||undefined,page:page.value,page_size:10}});if(listGuard.current(token)){items.value=r.data.items;total.value=r.data.total}}catch(e){error.value=errorText(e)}}
async function changeStore(){const token=taskGuard.begin();const scope=store.value;detailGuard.invalidate();simulation.value=undefined;simulations.value=[];simPage.value=1;audits.value=[];page.value=1;source.value='';selected.value=undefined;await load();await loadSimulations();if(!taskGuard.current(token))return;try{const rows=(await api.get('/agent/tasks',{params:{store_id:scope,status:'completed',page_size:100}})).data.items;if(taskGuard.current(token))tasks.value=rows}catch(e){if(taskGuard.current(token))error.value=errorText(e)}}
async function generate(){if(busy.value||!source.value)return;busy.value=true;error.value='';try{const r=await api.post('/decisions/generate',{source_task_id:source.value});message.value=`${r.data.reused?'已存在':'已生成'} ${r.data.proposals.length} 条建议。`+(r.data.skipped_reasons.length?'跳过原因：'+r.data.skipped_reasons.join('；'):'');await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function detail(row:Proposal){simulation.value=undefined;selected.value=undefined;audits.value=[];const token=detailGuard.begin();try{const result=await fetchDecisionBundle(row.proposal_id,async id=>(await api.get<Proposal>('/decisions/'+id)).data,async(id,store_id)=>(await api.get('/decisions/'+id+'/audit',{params:{store_id}})).data);if(detailGuard.current(token)){selected.value=result.proposal;audits.value=result.audit;comment.value=''}}catch(e){if(detailGuard.current(token))error.value=errorText(e)}}
async function review(action:string){if(!selected.value||reviewing.value)return;if(action==='reject'&&!comment.value.trim()){error.value='驳回必须填写有效原因';return}const proposal=selected.value;reviewing.value=true;try{await ElMessageBox.confirm(`确认${({approve:'批准',reject:'驳回',submit:'提交审核'} as Record<string,string>)[action]} ${proposal.sku}？批准不代表执行，本操作仅记录人工审批。`,'本地演示审批确认',{confirmButtonText:'确认审核',cancelButtonText:'取消',type:'warning'});await api.post('/decisions/'+proposal.proposal_id+'/'+action,{comment:comment.value},{params:{store_id:proposal.store_id}});error.value='';await detail(proposal);await load()}catch(e){if(e!=='cancel'&&e!=='close'){error.value=errorText(e);await detail(proposal)}}finally{reviewing.value=false}}
async function loadSimulations(){if(!store.value)return;const token=simGuard.begin();try{const r=await api.get('/simulations',{params:{store_id:store.value,page:simPage.value,page_size:10}});if(simGuard.current(token)){simulations.value=r.data.items;simTotal.value=r.data.total}}catch(e){error.value=errorText(e)}}
async function openSimulation(row:any){try{simulation.value=(await api.get('/simulations/'+row.simulation_id)).data}catch(e){error.value=errorText(e)}}
async function simulate(){if(!selected.value||simulating.value)return;const p=selected.value;simulating.value=true;try{await ElMessageBox.confirm('仅生成本地模拟工单，不修改实际经营数据，不调用平台接口。是否继续？','模拟执行确认',{confirmButtonText:'确认本地模拟',cancelButtonText:'取消',type:'warning'});const r=await api.post('/decisions/'+p.proposal_id+'/simulate',{});await openSimulation(r.data);await loadSimulations();error.value=''}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{simulating.value=false}}
onMounted(async()=>{try{stores.value=(await api.get<Store[]>('/stores')).data;store.value=stores.value[0]?.id;await changeStore();if(typeof route.query.proposal_id==='string')await detail({proposal_id:route.query.proposal_id} as Proposal)}catch(e){error.value=errorText(e)}})
</script>
<template><section><div class="eyebrow">DECISION WORKSPACE</div><h1>经营决策中心</h1><p>本地演示审批模式 · 批准不代表执行。没有真实身份认证，不执行预算调整或采购操作。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="filters"><el-select v-model="store" style="width:230px" @change="changeStore"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-select v-model="source" style="width:340px" placeholder="选择已完成的来源任务"><el-option v-for="t in tasks" :key="t.task_id" :label="t.user_query" :value="t.task_id"/></el-select><el-button type="primary" :disabled="!source" :loading="busy" @click="generate">生成经营建议</el-button></div><el-alert v-if="message" :title="message" type="info" :closable="false" style="margin-top:16px"/><div class="filters"><el-select v-model="kind" placeholder="全部类型" clearable style="width:200px" @change="page=1;load()"><el-option v-for="(label,key) in types" :key="key" :label="label" :value="key"/></el-select><el-select v-model="risk" placeholder="全部风险" clearable style="width:180px" @change="page=1;load()"><el-option label="高风险" value="high"/><el-option label="中风险" value="medium"/><el-option label="低风险" value="low"/></el-select><el-button @click="load">刷新</el-button></div><div class="panel"><el-table :data="items" empty-text="暂无决策单，请从已完成任务生成" @row-click="detail"><el-table-column prop="sku" label="SKU" min-width="130"/><el-table-column prop="title" label="建议" min-width="200"/><el-table-column label="风险" width="110"><template #default="{row}">{{({high:'⚠ 高风险',medium:'中风险',low:'低风险'} as Record<string,string>)[row.risk_level]}}</template></el-table-column><el-table-column label="状态" min-width="180"><template #default="{row}">{{statuses[row.status]||row.status}}</template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="10" :total="total" layout="prev,pager,next" @current-change="load"/></div><div v-if="selected" class="panel"><h2>{{selected.sku}} · {{selected.title}}</h2><p>{{selected.description}}</p><el-tag>{{statuses[selected.status]||selected.status}}</el-tag><div v-if="['draft','pending_review'].includes(selected.status)" class="panel"><p>固定审批身份：local-demo-reviewer（本地演示，非登录认证）。批准不代表执行。</p><el-input v-model="comment" type="textarea" :rows="3" maxlength="2000" placeholder="审核意见（驳回必填）"/><div style="margin-top:14px"><el-button v-if="selected.status==='draft'" :loading="reviewing" @click="review('submit')">提交审核</el-button><template v-else><el-button type="primary" :loading="reviewing" @click="review('approve')">批准（不执行）</el-button><el-button type="danger" plain :loading="reviewing" @click="review('reject')">驳回</el-button></template></div></div><div v-if="selected.status==='approved'" class="panel"><p>仅生成本地模拟工单，不修改实际经营数据。重复请求返回已有记录。</p><el-button :loading="simulating" type="primary" @click="simulate">模拟执行（非真实经营操作）</el-button></div><h3>审批历史（UTC）</h3><el-timeline v-if="audits.length"><el-timeline-item v-for="entry in audits" :key="entry.audit_id" :timestamp="entry.created_at"><strong>{{entry.from_status}} → {{entry.to_status}}</strong><p>{{entry.reviewer_id}} / {{entry.identity_source}}</p><p>{{entry.comment}}</p></el-timeline-item></el-timeline><p v-else>尚无审批记录</p><h3>建议措施（尚未执行）</h3><p>{{selected.suggested_action}}</p><router-link :to="'/agent-tasks?task_id='+selected.source_task_id">查看来源任务报告</router-link><h3>可信证据（生成时点复算）</h3><pre>{{JSON.stringify(selected.evidence_json,null,2)}}</pre><h3>业务限制</h3><p v-for="line in selected.limitations_json" :key="line">{{line}}</p></div><div class="panel"><h2>历史模拟执行记录</h2><p>模拟完成不代表经营指标改善。</p><el-button @click="loadSimulations">刷新模拟记录</el-button><el-table :data="simulations" empty-text="暂无本地模拟记录" @row-click="openSimulation"><el-table-column prop="sku" label="SKU" min-width="130"/><el-table-column prop="action_type" label="模拟动作" min-width="220"/><el-table-column prop="status" label="状态" min-width="210"/></el-table><el-pagination v-model:current-page="simPage" :page-size="10" :total="simTotal" layout="prev,pager,next" @current-change="loadSimulations"/></div><div v-if="simulation" class="panel"><h2>本地模拟结果 · {{simulation.status}}</h2><p style="overflow-wrap:anywhere">模拟 ID：{{simulation.simulation_id}}</p><p>simulation_only=true · 没有实际经营动作。</p><p>{{simulation.error_summary}}</p><p>{{simulation.output_json?.summary}}</p><router-link :to="'/decisions?proposal_id='+simulation.proposal_id" @click="detail({proposal_id:simulation.proposal_id} as Proposal)">查看来源决策</router-link> · <router-link :to="'/agent-tasks?task_id='+simulation.source_task_id">查看 Agent 任务</router-link><h3>模拟输出</h3><pre>{{JSON.stringify(simulation.output_json,null,2)}}</pre><h3>建议与审批输入快照</h3><pre>{{JSON.stringify(simulation.input_snapshot_json,null,2)}}</pre><h3>限制</h3><p v-for="line in simulation.limitations_json" :key="line">{{line}}</p></div></section></template>
<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f8f9fc;padding:16px;border-radius:8px;font-size:12px}h3{font-size:15px}.el-pagination{margin-top:16px}</style>
